<?php
require_once dirname(__DIR__).'/app/bootstrap.php';require_login();$uid=current_user_id();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);if($id>0)db()->prepare('UPDATE user_notifications SET read_at=CURRENT_TIMESTAMP WHERE id=:i AND user_id=:u')->execute([':i'=>$id,':u'=>$uid]);else db()->prepare('UPDATE user_notifications SET read_at=CURRENT_TIMESTAMP WHERE user_id=:u AND read_at IS NULL')->execute([':u'=>$uid]);redirect(app_path('notifications.php'));}$s=db()->prepare('SELECT * FROM user_notifications WHERE user_id=:u ORDER BY created_at DESC LIMIT 100');$s->execute([':u'=>$uid]);$items=$s->fetchAll();$pageTitle='Notifications | '.setting('site_name','LocalGuide');include __DIR__.'/includes/header.php';?>
<main id="main" class="container account-page lg4-page"><div class="lg4-page-heading"><span class="lg4-eyebrow">YOUR LOCAL GUIDE</span><h1>Notifications.</h1><p>Updates about your account, saved places and business conversations.</p></div><div class="content-panel lg4-notifications-panel"><div class="lg4-panel-top"><h2>Your updates</h2><?php if(unread_notification_count($uid)): ?><form method="post"><?= csrf_field() ?><button class="button button-outline button-small">Mark all as read</button></form><?php endif; ?></div><?php if($items): ?><div class="lg4-notification-list"><?php foreach($items as $item): ?><article class="lg4-notification <?= $item['read_at']?'read':'unread' ?>"><span class="lg4-notification-icon"><i class="fa-regular fa-bell"></i></span><div class="lg4-notification-copy"><strong><?= h($item['title']) ?></strong><p><?= h($item['body']) ?></p><small><?= h(format_date($item['created_at'])) ?></small><?php if($item['href']): ?><a href="<?= h(local_return_url((string)$item['href'])) ?>">Open update <i class="fa-solid fa-arrow-right"></i></a><?php endif; ?></div><?php if(!$item['read_at']): ?><form method="post"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$item['id'] ?>"><button aria-label="Mark as read" class="round-link"><i class="fa-solid fa-check"></i></button></form><?php endif; ?></article><?php endforeach; ?></div><?php else: ?><div class="empty-state"><span><i class="fa-regular fa-bell"></i></span><h3>You're all caught up.</h3><p>New account and business updates will appear here.</p></div><?php endif; ?></div></main><?php include __DIR__.'/includes/footer.php';?>
